# Generated by GitHub Copilot - Oct-05-2026
def minimal_config(tmp_path, monkeypatch):
    """Use an imported synthetic transcript with all optional capabilities disabled."""
    cfg = load_config()
    transcript = tmp_path / "transcript.json"
    write_json(transcript, {"words": []})
    cfg["transcription"]["import_file"] = str(transcript)
    for name in ("diarization", "vision", "scenes", "ocr", "audio_events"):
        cfg[name]["enabled"] = False
    cfg["preview"]["enabled"] = False
    cfg["semantic_analysis"]["backend"] = "heuristic"
    monkeypatch.setattr(preflight.shutil, "which", lambda name: "fixture/" + name)
    return cfg


# Generated by GitHub Copilot - Oct-05-2026
def test_disabled_optional_features_do_not_fail(tmp_path, monkeypatch):
    """Missing optional packages must not block an explicitly disabled feature."""
    cfg = minimal_config(tmp_path, monkeypatch)
    monkeypatch.setattr(preflight, "_import_check", lambda *args: pytest.fail("disabled dependency probed"))
    report = preflight.require_preflight(cfg, tmp_path / "output")
    assert report["ready"]
    assert report["capabilities"]["diarization"]["status"] == "DISABLED"
    assert report["runtime_target_match"] == (sys.platform == "win32" and sys.version_info[:2] == (3, 11))


