# Generated by GitHub Copilot - Oct-05-2026
def test_token_values_never_enter_preflight_report(tmp_path, monkeypatch):
    """Only presence is observable; fabricated credentials stay in memory."""
    cfg = minimal_config(tmp_path, monkeypatch)
    fake = "hf_" + "a" * 30
    monkeypatch.setenv("HF_TOKEN", fake)
    report = preflight.run_preflight(cfg, tmp_path)
    assert fake not in json.dumps(report)
    assert fake not in scrub("access denied " + fake)
    assert "sk-" + "b" * 30 not in scrub("sk-" + "b" * 30)


# Generated by GitHub Copilot - Oct-05-2026
def test_import_errors_are_scrubbed_and_never_repair_global_python(monkeypatch):
    """Missing native dependencies cannot leak credentials or alter global Python."""
    fake = "hf_" + "c" * 30
    def failing_import(name):
        """Model a loader failure containing an untrusted credential string."""
        raise ImportError(fake)
    monkeypatch.setattr(preflight.importlib, "import_module", failing_import)
    cfg = load_config()
    cfg["preflight"]["allow_self_repair"] = True
    monkeypatch.setattr(preflight.sys, "prefix", preflight.sys.base_prefix)
    monkeypatch.setattr(preflight.subprocess, "run", lambda *args, **kwargs: pytest.fail("global repair attempted"))
    result = preflight._import_check("mediapipe", cfg)
    assert not result["ok"] and fake not in json.dumps(result)


# Generated by GitHub Copilot - Oct-05-2026
def test_normal_install_includes_enabled_extras_and_models(tmp_path, monkeypatch):
    """Inspect the real installer command path with isolated subprocess fixtures."""
    import importlib.util
    from pathlib import Path
    from types import SimpleNamespace
    spec = importlib.util.spec_from_file_location("installer", Path(__file__).resolve().parents[2] / "install.py")
    installer = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(installer)
    monkeypatch.setattr(installer, "ROOT", tmp_path)
    monkeypatch.setattr(installer.sys, "version_info", (3, 11, 9))
    monkeypatch.setattr(installer.sys, "argv", ["install.py"])
    monkeypatch.setattr(installer.platform, "architecture", lambda: ("64bit", ""))
    monkeypatch.setattr(installer.venv.EnvBuilder, "create", lambda *args: None)
    monkeypatch.setattr(installer.subprocess, "run", lambda *args, **kwargs: SimpleNamespace(stdout="3.11\n"))
    commands = []
    monkeypatch.setattr(installer, "run", lambda args: commands.append([str(value) for value in args]))
    installer.main()
    installs = next(command for command in commands if any(value.endswith("requirements.txt") for value in command))
    assert any(Path(value).as_posix().endswith("requirements/diarization.txt") for value in installs)
    assert any(Path(value).as_posix().endswith("requirements/vision.txt") for value in installs)
    assert any(command[-1].endswith("download_models.py") for command in commands)
    assert not any(Path(value).as_posix().endswith("requirements/ocr.txt") for value in installs)


