def test_full_local_model_files_still_require_actual_model_load(tmp_path,monkeypatch):
    """A directory with plausible filenames cannot pretend to be a usable pipeline."""
    cfg=load_config()
    cfg['offline']=True
    model=tmp_path/'model'
    model.mkdir()
    (model/'config.yaml').write_text('fixture',encoding='utf-8')
    (model/'pytorch_model.bin').write_bytes(b'fixture')
    cfg['diarization']['model']=str(model)
    monkeypatch.setattr(preflight,'validate_pipeline_model',lambda cfg: {'ok':False,'model_load':'fixture-failed'})
    result=preflight._model_access(cfg)
    assert result['cached_model'] and not result['ok']
    assert result['model_load']=='fixture-failed'


