def test_auto_device_does_not_mask_nvidia_cuda_failure(tmp_path,monkeypatch):
    """A NVIDIA machine with broken CT2/DLLs cannot silently switch to CPU."""
    from ldporto import gpu_runtime,ollama_local
    cfg=minimal_config(tmp_path,monkeypatch)
    cfg['transcription']['import_file']=None
    monkeypatch.setattr(preflight,'_import_check',lambda *args:{'ok':True})
    monkeypatch.setattr(gpu_runtime,'ctranslate2_cuda_info',lambda:{'device_count':0,'dll_status':{'status':'missing'}})
    monkeypatch.setattr(ollama_local,'nvidia_smi',lambda:{'available':True,'gpus':[{'name':'fixture'}]})
    report=preflight.run_preflight(cfg,tmp_path)
    assert not report['capabilities']['asr']['checks']['cuda']['ok']
    cfg['device']='cpu'
    assert preflight.run_preflight(cfg,tmp_path)['capabilities']['asr']['checks']['cuda']['ok']


