def test_waveform_diarization_diagnoses_unused_decoder_without_blocking(tmp_path,monkeypatch):
    """An unused file decoder does not mask the required pyannote/model load checks."""
    from types import SimpleNamespace
    cfg=minimal_config(tmp_path,monkeypatch)
    cfg['diarization']['enabled']=True
    monkeypatch.setattr(preflight,'_import_check',lambda name,cfg:{'ok':name!='torchcodec'})
    monkeypatch.setattr(preflight,'_model_access',lambda cfg:{'ok':True,'model_load':'fixture_verified'})
    monkeypatch.setitem(sys.modules,'torch',SimpleNamespace(cuda=SimpleNamespace(is_available=lambda:False)))
    report=preflight.run_preflight(cfg,tmp_path)
    capability=report['capabilities']['diarization']
    assert capability['status']=='READY'
    assert capability['checks']['torchcodec']['ok'] is False
    assert capability['checks']['torchcodec']['required'] is False